CREATE TABLE tech_eval (
  deal_id       TEXT PRIMARY KEY,
  track         TEXT,
  agency1       TEXT,
  grade1        TEXT,
  agency2       TEXT,
  grade2        TEXT
);
CREATE TABLE underwriter (
  rcept_no TEXT NOT NULL,
  row_no   INTEGER NOT NULL,
  actsen   TEXT,    -- 인수인구분 (대표주관회사 등)
  actnmn   TEXT,    -- 인수인명
  stksen   TEXT,
  udtcnt   TEXT,    -- 인수수량
  udtamt   TEXT,    -- 인수금액
  udtprc   TEXT,    -- 인수대가
  udtmth   TEXT,    -- 인수방법
  PRIMARY KEY (rcept_no, row_no)
);
